"""Generate the findings narrative from reproducible analytical tables."""

from __future__ import annotations

import calendar

import pandas as pd

LABELS = {"GMB": "Green Minibuses", "RMB": "Red Minibuses (estimated)", "PLB": "Total PLB (includes estimates)", "MTR": "MTR railway services", "FRANCHISED_BUS": "Franchised buses"}
ORDER = ["GMB", "RMB", "PLB", "MTR", "FRANCHISED_BUS"]


def _table(headers, rows):
    return "\n".join(["| " + " | ".join(headers) + " |", "| " + " | ".join("---" for _ in headers) + " |", *["| " + " | ".join(str(value) for value in row) + " |" for row in rows]])


def render_findings(tables: dict[str, pd.DataFrame], summary: dict) -> str:
    endpoints = tables["endpoint_comparison"].set_index("mode")
    shares = tables["annual_market_share"].pivot(index="mode", columns="year", values="share_pct")
    composition = tables["annual_minibus_composition"].pivot(index="mode", columns="year", values="share_of_plb_pct")
    segments = tables["trend_segments"].set_index(["segment", "mode"])
    contributions = tables["minibus_change_contributions"].set_index(["segment", "mode"])
    annual_fleet = tables["annual_fleet"].set_index(["year", "mode"])
    plb_share_2015 = shares.loc[["GMB", "RMB"], 2015].sum()
    plb_share_2025 = shares.loc[["GMB", "RMB"], 2025].sum()
    gmb, rmb, plb = (endpoints.loc[mode] for mode in ["GMB", "RMB", "PLB"])
    lines = ["# Hong Kong Minibus Ridership: Exploratory Research Findings", "", "## Executive summary", "",
        "This study follows published passenger journeys from January 2015 through December 2025 using one internally consistent Transport Department snapshot. The five principal findings are:", "",
        f"1. **PLB journeys are lower over the decade, with a much larger relative reduction in RMB.** PLB fell from {plb.journeys_2015_thousands / 1000:,.3f} million to {plb.journeys_2025_thousands / 1000:,.3f} million journeys ({plb.change_2015_2025_pct:+.2f}%). GMB changed {gmb.change_2015_2025_pct:+.2f}%; estimated RMB changed {rmb.change_2015_2025_pct:+.2f}%.",
        f"2. **The recent PLB recovery is GMB-driven.** Between 2023 and 2025 GMB rose {segments.loc[('2023_to_2025','GMB'), 'change_pct']:.2f}% while RMB fell {abs(segments.loc[('2023_to_2025','RMB'), 'change_pct']):.2f}%. GMB's share of PLB journeys increased from {composition.loc['GMB',2015]:.2f}% in 2015 to {composition.loc['GMB',2025]:.2f}% in 2025.",
        f"3. **Recovery differs sharply across modes.** Full-year 2025 was {plb.recovery_2025_vs_2019_pct:.2f}% of 2019 for PLB, {gmb.recovery_2025_vs_2019_pct:.2f}% for GMB and {rmb.recovery_2025_vs_2019_pct:.2f}% for RMB, compared with {endpoints.loc['MTR','recovery_2025_vs_2019_pct']:.2f}% for MTR and {endpoints.loc['FRANCHISED_BUS','recovery_2025_vs_2019_pct']:.2f}% for franchised buses.",
        f"4. **PLB's relative position weakened within the defined comparison group.** Its combined share moved from {plb_share_2015:.2f}% to {plb_share_2025:.2f}% ({plb_share_2025-plb_share_2015:+.2f} percentage points). This is a share of GMB + RMB + MTR railway + franchised bus journeys, not all Hong Kong public transport.",
        f"5. **Fleet contraction alone does not describe the passenger changes.** December RMB licensed stock fell from {annual_fleet.loc[(2015,'RMB'),'december_licensed_vehicles']:,.0f} to {annual_fleet.loc[(2025,'RMB'),'december_licensed_vehicles']:,.0f}; GMB stock rose from {annual_fleet.loc[(2015,'GMB'),'december_licensed_vehicles']:,.0f} to {annual_fleet.loc[(2025,'GMB'),'december_licensed_vehicles']:,.0f}. Both categories had lower annual journeys per licensed vehicle-day proxy in 2025 than in 2015.", "",
        "These findings are descriptive. RMB volumes are estimates; PLB and every comparison-group denominator contain that estimated component. None of the results identifies individual mode switching or a causal mechanism.", "",
        "## Research questions", "",
        "The analysis addresses the seven agreed questions: long-term ridership direction; GMB/RMB composition; disruption-period patterns; comparison-group shares; recovery against pre-pandemic benchmarks; calendar-month patterns; and licensed fleet context. The [research plan](../docs/project_plan.md) records their scope and interpretation limits.", "",
        "## Data sources and analytical scope", "",
        "The source is the Hong Kong Transport Department's Monthly Traffic and Transport Digest: Table 2.1 monthly passenger journeys, Table 2.1S monthly average daily journeys and Table 2.2 minibus licensed stock/capacity. The preserved files were retrieved on 11 October 2026 and report a dataset revision date of 21 September 2026. All five analytical series contain 132 monthly observations. [Verified inventory](../docs/data_sources.md), [prepared field definitions](../docs/data_dictionary.md).", "",
        "PLB equals GMB + RMB. MTR equals MTR Lines + Airport Express + Light Rail and includes cross-boundary services in the MTR Lines category. Hong Kong Tramways and MTR buses are excluded. Franchised bus journeys include each contemporaneous franchise once; preparation handles the July 2023 Citybus/NWFB merger. Changing MTR service coverage limits like-for-like network interpretation.", "",
        "### Annual-reference investigation", "",
        "The six exceptions compare current monthly sums with older provisional minibus totals. TD permits revisions incorporating updated figures. Current 2024 sums agree with the later December 2025 unflagged publication within rounding tolerance; no inspected note establishes a minibus definition change explaining these exceptions. Publication updates are therefore the best-supported interpretation, but the specific revision reasons remain unresolved. Original observations are retained. [Detailed official evidence and sensitivity investigation](reference_discrepancies.md).", ""]
    refs = tables["annual_reference_comparisons"]
    lines += [_table(["Older publication", "Year", "Mode", "Reference, thousand", "Current sum, thousand", "Difference, thousand", "Reference flag"], [["ATD 2025" if row.publication.startswith("Annual") else "December 2025", row.year, row.mode, f"{row.reference_value_thousands:,.3f}", f"{row.current_snapshot_total_thousands:,.3f}", f"{row.difference_thousands:+,.3f}", row.source_indicator or "blank"] for row in refs.itertuples() if not row.within_rounding_tolerance]), "",
        f"Replacing only the 2025 endpoint with the older annual reference changes the decade percentage change by at most {refs.endpoint_2015_change_sensitivity_pp.abs().max():.6f} percentage points and the 2019 recovery index by at most {refs.endpoint_2019_recovery_sensitivity_pp.abs().max():.6f} points. Those differences do not change the main annual conclusions. They are not uncertainty bounds for RMB estimation. The detailed investigation also identifies larger December monthly revisions, so precise monthly comparisons must use a consistent vintage. [Comparison output](../analysis/outputs/annual_reference_comparisons.csv).", "",
        "## Methodology", "",
        "Annual flows sum twelve monthly totals in thousands; tables display millions where stated. Year-over-year change compares consecutive complete years or the same calendar month one year earlier. Absolute change is current minus baseline. Recovery is 100 × a mode's annual journeys / its own 2019 annual journeys: 100% denotes the benchmark and values above 100% exceed it. An alternative benchmark uses mean annual journeys in 2015–2018.", "",
        "Periods are pre-pandemic 2015–2019, disruption 2020–2022 and post-pandemic 2023–2025. Comparisons use mean annual journeys and day-weighted daily rates, rather than contrasting unequal-length period totals. These are timing labels rather than a causal design.", "",
        "Shares divide each of GMB, RMB, MTR and franchised buses by their combined journeys. Annual shares use annual flow totals, not an average of monthly shares. Combined PLB share is GMB share + RMB share and is not added to the four components again.", "",
        "Calendar profiles use average daily journeys. To reduce differences in annual demand levels, each monthly daily rate is divided by that year's annual total / actual calendar days and multiplied by 100; profiles then average the same calendar month equally across years within each period. This normalization does not remove within-year trend or changing calendar effects. Population standard deviations and coefficients of variation describe the observed year-specific values, not sampling uncertainty.", "",
        "The monthly fleet indicator is daily journeys × 1,000 / month-end licensed vehicles. The annual indicator is annual journeys × 1,000 / Σ(month-end licensed vehicles × calendar days), using licensed vehicle-days as a proxy. December stocks and the arithmetic mean of twelve month-end stocks are distinct summaries. The indicator does not measure occupancy, deployment or operational productivity. [Full analytical methods and output dictionary](../docs/analysis_methodology.md).", "",
        "## Key quantitative findings", "", "### 1. Decade reduction differs substantially between GMB and RMB", ""]
    rows = []
    for mode in ORDER:
        row = endpoints.loc[mode]
        rows.append([LABELS[mode], f"{row.journeys_2015_thousands/1000:,.3f}", f"{row.journeys_2019_thousands/1000:,.3f}", f"{row.journeys_2025_thousands/1000:,.3f}", f"{row.absolute_change_2015_2025_thousands/1000:+,.3f}", f"{row.change_2015_2025_pct:+.2f}%", f"{row.recovery_2025_vs_2019_pct:.2f}%"])
    lines += [_table(["Series", "2015, million", "2019, million", "2025, million", "2015–2025 Δ, million", "Decade change", "2025 / 2019"], rows), "",
        f"PLB lost {abs(plb.absolute_change_2015_2025_thousands)/1000:,.3f} million annual journeys. Estimated RMB accounts for {contributions.loc[('2015_to_2025','RMB'),'contribution_to_plb_change_pct']:.2f}% of that absolute reduction despite its smaller starting volume. Before the disruption period, PLB had already fallen {abs(segments.loc[('pre_pandemic','PLB'),'change_pct']):.2f}% and RMB {abs(segments.loc[('pre_pandemic','RMB'),'change_pct']):.2f}% from 2015 to 2019; both declined in each of the four annual transitions. Thus the decade reduction cannot be described solely as a post-2020 phenomenon. It does not establish the causes of either earlier or later reductions. [Endpoints](../analysis/outputs/endpoint_comparison.csv), [trend segments](../analysis/outputs/trend_segments.csv), [change contributions](../analysis/outputs/minibus_change_contributions.csv).", "",
        "![Monthly minibus journeys](../analysis/figures/01_monthly_minibus_ridership.png)", "",
        "![Annual minibus journeys](../analysis/figures/02_annual_minibus_ridership.png)", "",
        "Annual minibus levels and growth are available for every year in [annual_ridership.csv](../analysis/outputs/annual_ridership.csv); first-year growth is unavailable within this window. The following table shows the complete PLB sequence alongside its components.", ""]
    ann = tables["annual_ridership"].set_index(["year", "mode"])
    lines += [_table(["Year", "GMB, million", "RMB, million (estimated)", "PLB, million", "PLB annual Δ, million", "PLB YoY"], [[year, f"{ann.loc[(year,'GMB'),'passenger_journeys_thousands']/1000:,.3f}", f"{ann.loc[(year,'RMB'),'passenger_journeys_thousands']/1000:,.3f}", f"{ann.loc[(year,'PLB'),'passenger_journeys_thousands']/1000:,.3f}", "—" if year == 2015 else f"{ann.loc[(year,'PLB'),'absolute_yoy_change_thousands']/1000:+,.3f}", "—" if year == 2015 else f"{ann.loc[(year,'PLB'),'yoy_change_pct']:+.2f}%"] for year in range(2015,2026)]), "",
        "### 2. Recent growth is GMB-driven and composition continues to shift", "",
        f"GMB's PLB journey share rose from {composition.loc['GMB',2015]:.2f}% to {composition.loc['GMB',2025]:.2f}% ({composition.loc['GMB',2025]-composition.loc['GMB',2015]:+.2f} percentage points). Estimated RMB's share moved from {composition.loc['RMB',2015]:.2f}% to {composition.loc['RMB',2025]:.2f}%. From 2023 to 2025, GMB added {segments.loc[('2023_to_2025','GMB'),'absolute_change_thousands']/1000:,.3f} million journeys while RMB lost {abs(segments.loc[('2023_to_2025','RMB'),'absolute_change_thousands'])/1000:,.3f} million; PLB gained {segments.loc[('2023_to_2025','PLB'),'absolute_change_thousands']/1000:,.3f} million ({segments.loc[('2023_to_2025','PLB'),'change_pct']:+.2f}%).", "",
        f"GMB increased in every annual transition from 2022 to 2025; RMB decreased in all three. In 2025 alone, GMB grew {ann.loc[(2025,'GMB'),'yoy_change_pct']:.2f}%, RMB changed {ann.loc[(2025,'RMB'),'yoy_change_pct']:+.2f}%, and PLB grew {ann.loc[(2025,'PLB'),'yoy_change_pct']:.2f}%. This supports a description of partial, uneven recovery rather than common stabilization across minibus categories. GMB accounts for more than the net PLB increase because RMB offsets part of its gain; change contributions are not market shares. Composition alone cannot show that the same passengers moved between services. [Annual composition](../analysis/outputs/annual_minibus_composition.csv), [segment changes](../analysis/outputs/trend_segments.csv).", "",
        "![GMB and RMB composition](../analysis/figures/03_minibus_composition.png)", "",
        "### 3. Recovery remains incomplete for minibuses and depends on the benchmark", "",
        f"With 2019 fixed at 100%, PLB reaches {plb.recovery_2025_vs_2019_pct:.2f}% in 2025, compared with MTR's {endpoints.loc['MTR','recovery_2025_vs_2019_pct']:.2f}%. Estimated RMB remains at {rmb.recovery_2025_vs_2019_pct:.2f}% of its benchmark. MTR exceeding its own 2019 journeys does not prove substitution from minibuses: service coverage and other demand conditions also differ. [Recovery output](../analysis/outputs/recovery_2019.csv).", "",
        "![Annual recovery against 2019](../analysis/figures/04_recovery_2019_baseline.png)", "",
        "The 2015–2018 mean is a useful sensitivity benchmark because 2019 is not assumed to represent an undisturbed or fixed demand level. The alternative changes the level of recovery; it does not erase the GMB/RMB difference.", "",
        _table(["Series", "2025 / 2019", "2025 / mean annual 2015–2018"], [[LABELS[mode], f"{endpoints.loc[mode,'recovery_2025_vs_2019_pct']:.2f}%", f"{endpoints.loc[mode,'recovery_2025_vs_2015_2018_mean_pct']:.2f}%"] for mode in ORDER]), "",
        "Period comparisons below use mean annual journeys (million), so five-year and three-year groups are comparable in scale. Day-weighted daily rates are also saved in [period_summary.csv](../analysis/outputs/period_summary.csv).", ""]
    period = tables["period_summary"].set_index(["period", "mode"])
    lines += [_table(["Series", "2015–2019 mean", "2020–2022 mean", "2023–2025 mean"], [[LABELS[mode], *[f"{period.loc[(name,mode),'mean_annual_passenger_journeys_thousands']/1000:,.3f}" for name in ["pre_pandemic","pandemic_disruption","post_pandemic"]]] for mode in ORDER]), "",
        "Monthly totals and daily rates identify different trough months for several modes. Short February totals must not be treated as directly equivalent to daily demand. These are the minima observed within the complete study window; their timing coincides with the disruption period, without isolating a causal effect.", ""]
    minima = tables["monthly_minima"].set_index(["mode", "metric"])
    lines += [_table(["Series", "Lowest monthly total", "Million journeys", "Lowest daily rate month", "Thousand journeys/day"], [[LABELS[mode], minima.loc[(mode,"passenger_journeys_thousands"),"month"][:7], f"{minima.loc[(mode,'passenger_journeys_thousands'),'value']/1000:,.3f}", minima.loc[(mode,"average_daily_journeys_thousands"),"month"][:7], f"{minima.loc[(mode,'average_daily_journeys_thousands'),'value']:,.3f}"] for mode in ORDER]), "",
        "[Trough values and same-month 2019 comparisons](../analysis/outputs/monthly_minima.csv).", "",
        "### 4. Public light buses lost comparison-group share", "",
        f"Combined PLB share fell from {plb_share_2015:.2f}% in 2015 to {plb_share_2025:.2f}% in 2025 ({plb_share_2025-plb_share_2015:+.2f} percentage points). RMB's contribution moved from {shares.loc['RMB',2015]:.2f}% to {shares.loc['RMB',2025]:.2f}%; GMB's from {shares.loc['GMB',2015]:.2f}% to {shares.loc['GMB',2025]:.2f}%. MTR's share rose from {shares.loc['MTR',2015]:.2f}% to {shares.loc['MTR',2025]:.2f}%. Relative shares reflect changes in both numerator and denominator, not just minibus demand. [Annual shares](../analysis/outputs/annual_market_share.csv), [monthly shares](../analysis/outputs/monthly_market_share.csv).", "",
        _table(["Nonoverlapping component", "2015 share", "2019 share", "2025 share"], [[LABELS[mode], *[f"{shares.loc[mode,year]:.2f}%" for year in [2015,2019,2025]]] for mode in ["GMB","RMB","MTR","FRANCHISED_BUS"]]), "",
        "![Comparison-group annual shares](../analysis/figures/05_comparison_group_market_share.png)", "",
        "The four components sum to 100%. PLB is their GMB/RMB subtotal, not a fifth additive share. Every denominator includes estimated RMB, even when a displayed numerator is reported.", "",
        "### 5. Licensed fleet context reinforces the need to separate categories", ""]
    fleet_rows = []
    for mode in ["GMB", "RMB"]:
        start, end = annual_fleet.loc[(2015,mode)], annual_fleet.loc[(2025,mode)]
        fleet_rows.append([LABELS[mode], f"{start.december_licensed_vehicles:,.0f}", f"{end.december_licensed_vehicles:,.0f}", f"{100*(end.december_licensed_vehicles/start.december_licensed_vehicles-1):+.2f}%", f"{start.average_daily_journeys_per_licensed_vehicle:.2f}", f"{end.average_daily_journeys_per_licensed_vehicle:.2f}", f"{100*(end.average_daily_journeys_per_licensed_vehicle/start.average_daily_journeys_per_licensed_vehicle-1):+.2f}%"])
    lines += [_table(["Series", "Dec 2015 vehicles", "Dec 2025 vehicles", "Stock change", "2015 journeys/vehicle-day proxy", "2025 proxy", "Proxy change"], fleet_rows), "",
        "GMB's licensed stock increased while its decade passenger total decreased; estimated RMB journeys fell faster than its licensed stock. Both fleet-normalized indicators were lower than their 2015 benchmarks. That is descriptive stock context, not evidence that operating vehicles became less productive. Month-end stocks do not reveal daily deployment, and RMB estimation uses licensed fleet information, creating a partly mechanical relationship. Comparable RMB mileage is unavailable. [Annual fleet summaries](../analysis/outputs/annual_fleet.csv), [monthly normalized indicators](../analysis/outputs/fleet_normalized.csv).", "",
        "![Licensed fleet and descriptive fleet-normalized journeys](../analysis/figures/07_fleet_and_fleet_normalized_ridership.png)", "",
        "## Calendar-month patterns and statistical interpretation", "",
        "The normalized daily profiles show moderate calendar-month variation outside the disruption period. They describe observed averages, with no claim of statistical significance or a stable recurring seasonal mechanism. Raw monthly means, daily means, population standard deviations and coefficients of variation are saved for inspection.", ""]
    ranges = tables["seasonality_ranges"].set_index(["period","mode"])
    seasonal_rows = []
    for mode in ["GMB","RMB"]:
        for name, label in [("pre_pandemic","2015–2019"),("post_pandemic","2023–2025")]:
            row = ranges.loc[(name,mode)]
            seasonal_rows.append([LABELS[mode], label, calendar.month_abbr[int(row.peak_calendar_month)], f"{row.peak_daily_index:.2f}", calendar.month_abbr[int(row.trough_calendar_month)], f"{row.trough_daily_index:.2f}", f"{row.range_index_points:.2f}"])
    lines += [_table(["Series", "Period", "Peak month", "Peak index", "Trough month", "Trough index", "Range, index points"], seasonal_rows), "",
        "Index 100 is the corresponding year's annual day-weighted daily level. The pre-period has five values per calendar month and the post-period three; these are small collections of years, not independent random observations. Normalization removes annual level differences but retains within-year growth/decline, movable calendar effects and service changes. In particular, RMB's ongoing decline can influence a profile whose later months are lower. The broader disruption-period profile combines sharp demand interruptions with calendar variation and must not be interpreted as ordinary seasonality. [Profiles and dispersion](../analysis/outputs/seasonality.csv), [profile ranges](../analysis/outputs/seasonality_ranges.csv).", "",
        "![Calendar-day-adjusted profiles](../analysis/figures/06_minibus_seasonality.png)", "",
        "## Industry and transport implications", "",
        "The aggregate evidence describes an increasingly GMB-dominated minibus industry. GMB's recent growth and RMB's continued reduction deserve separate treatment in transport planning and industry discussion. A combined PLB headline conceals that difference. The smaller PLB comparison-group share and incomplete recovery indicate persistent departures from historical benchmarks, while MTR's different trajectory shows that the result is mode-specific rather than a uniform pattern across the comparison group.", "",
        "These patterns could reflect changes in route coverage, service supply, fares, demographics, visitor travel or reporting/estimation methods. This dataset does not measure their individual effects. Establishing structural causes would require additional verified evidence and an appropriate research design; the descriptive patterns alone cannot attribute losses to competition or permanent passenger switching.", "",
        "## Reproducibility and analytical checks", "",
        f"The analysis run passed **{summary['check_counts']['pass']} checks**, recorded **{summary['check_counts']['warning']} limitations**, and had **{summary['check_counts']['fail']} failed checks**. The six analytical SQL queries agree with independent Pandas calculations for annual aggregation/growth, same-month growth, annual/monthly shares, recovery and fleet normalization. Checks also verify annual/monthly PLB identity, 100% share totals, calendar weighting, normalized baselines, CSV round-trips and unchanged Phase 1/2 input bytes. [Machine-readable analysis summary](../analysis/outputs/analysis_summary.json), [SQL query documentation](../sql/analysis/README.md).", "",
        "Every numeric statement in this report is generated from the linked tables by [analysis_report.py](../src/hk_minibus/analysis_report.py). Calculations are in [analysis.py](../src/hk_minibus/analysis.py); [analysis_pipeline.py](../src/hk_minibus/analysis_pipeline.py) verifies inputs and cross-checks the independent SQL outputs. Values are rounded only for display. The discrepancy investigation additionally records explicitly transcribed official reference evidence.", "",
        "From the repository root, after installing requirements:", "",
        "```powershell", ".\\.venv\\Scripts\\python.exe scripts\\analyze_data.py", ".\\.venv\\Scripts\\python.exe -m pytest -q --basetemp analysis/.pytest-tmp-run -p no:cacheprovider", "```", "",
        "## Data limitations", "",
        "- RMB estimates have no published confidence intervals or complete parameter history. The source-vintage sensitivity exercise is not a measurement-error estimate.",
        "- Journeys are aggregate patronage, not unique people. Shares describe only the chosen comparison group.",
        "- The current snapshot is internally consistent, but earlier provisional publications differ. Detailed revision reasons remain unresolved.",
        "- MTR services changed across the study; the bus merger changes component labels, while preparation maintains the contemporaneous total boundary.",
        "- Period comparisons and recovery ratios have no causal identification; 2019 and earlier mean baselines give different answers.",
        "- Calendar profiles use few years and retain within-year trend and changing calendar effects. No hypothesis test or inferential interval is asserted.",
        "- Licensed vehicles and carrying capacity do not measure operating deployment or occupancy; RMB mileage is unsupported.", "",
        "## Conclusion", "",
        "Published PLB journeys decreased over the decade, while the subsequent recovery is concentrated in GMB and the estimated RMB series remains substantially lower. The shift in composition, comparison-group share and licensed fleet context supports a differentiated historical account of the industry. It establishes what changed in these published aggregates, while leaving the underlying causes and estimation uncertainty open.", ""]
    return "\n".join(lines)
